import {SHIP_SCALE,SHIP_Y} from './ship-scale.js';
import {THREE,scene,ship,box,sphere,cylinder,material,mesh,glow,ring} from './world.js';
import {FLAG_SITES,LANDING_BAYS,FACTIONS,flagCounts} from './science-match.js';
export function createScienceWorld(state,world){const home=new THREE.Group(),frontier=new THREE.Group(),props=new THREE.Group();world.root.add(home,frontier,props);const cover=[];function emblem(i,parent,x=0,y=.04,z=6.5){let geo;if(i===0){const shape=new THREE.Shape();shape.moveTo(0,.6);shape.lineTo(-.55,-.4);shape.lineTo(.55,-.4);shape.closePath();geo=new THREE.ShapeGeometry(shape);}else if(i===1)geo=new THREE.CircleGeometry(.5,24);else geo=new THREE.PlaneGeometry(.85,.85);const mark=mesh(geo,new THREE.MeshBasicMaterial({color:'#f4ecd8',side:THREE.DoubleSide}),parent,x,y,z);mark.rotation.x=-Math.PI/2;if(i===2)mark.rotation.z=Math.PI/4;mark.castShadow=false;}
// Planet A: four distinct bays around a central industrial gantry.
for(const [i,x,z]of[[0,0,0],[1,-60,-44],[2,60,-44],[3,0,-92]]){const g=new THREE.Group();g.position.set(x,0,z);g.scale.set(SHIP_SCALE,1,SHIP_SCALE);home.add(g);cylinder(7.8,8,.15,'#c7ac88',g,0,-.11,0,48);emblem(i,g);ring(7.4,.12,FACTIONS[i].color,g,.015);for(const sign of[-1,1]){box(.15,.08,9,FACTIONS[i].color,g,sign*6.5,.04,0);box(.5,1.7,.5,'#76606a',g,sign*7,.8,-5);}for(let k=0;k<5;k++)box(.5,.015,.14,'#eee2c6',g,-1.4+k*.7,.03,6.2);}
const gantry=new THREE.Group();gantry.position.set(0,0,-46);gantry.scale.setScalar(2.2);home.add(gantry);for(const x of[-5,5]){box(.65,9,.65,'#b4794f',gantry,x,4.5,0);box(1.5,.3,1.4,'#776371',gantry,x,.1,0);}box(11,.7,.8,'#ce9358',gantry,0,8.8,0);box(2,.8,1.4,'#584c61',gantry,0,8.1,0);cylinder(.035,.035,4,'#8f7b75',gantry,0,5.6,0,8);mesh(new THREE.TorusGeometry(.3,.07,8,14,Math.PI*1.5),material('#5f5265'),gantry,0,3.5,0);
for(let z=-32;z<15;z+=3)box(.1,.018,1,'#dfb58b',home,0,-.01,z);const hoist=new THREE.Group();hoist.position.set(-40,0,6);home.add(hoist);box(.25,4.8,.25,'#d8a26d',hoist,0,2.4,0);box(2.8,.25,.3,'#d8a26d',hoist,1.2,4.7,0);cylinder(.025,.025,2,'#7c6470',hoist,2.3,3.6,0,8);const tank=cylinder(.5,.5,1.5,'#debf91',hoist,2.3,1.6,0,20);for(const y of[1,2.2])mesh(new THREE.TorusGeometry(.5,.065,6,20),material('#8a6460'),hoist,2.3,y,0).rotation.x=Math.PI/2;
const receiver=new THREE.Group();receiver.position.set(0,0,40);home.add(receiver);cylinder(2.4,2.6,.2,'#bd936e',receiver,0,.1,0,12);ring(2.2,.05,'#d7e1a6',receiver,.23);for(let i=0;i<8;i++)cylinder(.15,.2,.8,'#72606d',receiver,-1.4+(i%4)*.9,.5,Math.floor(i/4)*.8-.4,12);receiver.userData.action={type:'receiver'};world.targets.push(receiver);
const shop=new THREE.Group();shop.position.set(-38,0,16);home.add(shop);box(1.6,1.2,1,'#9d7658',shop,0,.6,0);box(1.4,.15,1.1,'#cfab7e',shop,0,1.27,0);glow(1,.25,.025,'#e8bd7a',shop,0,1.02,.52);shop.userData.action={type:'shop'};world.targets.push(shop);
// A warm, rounded ready room behind the original character models.
const readyRoom=new THREE.Group();world.stage.add(readyRoom);box(15,.2,8,'#b87848',readyRoom,0,-.3,-1.6);box(15,5,.4,'#8c5a48',readyRoom,0,2.1,-2.2);for(let x=-6;x<=6;x+=3){box(.12,5,.25,'#5c4552',readyRoom,x,2.1,-1.95);box(2,.06,.35,'#e6bd7b',readyRoom,x,4.2,-1.7);}for(let y of[.5,3.6]){const p=cylinder(.13,.13,14,'#71515c',readyRoom,0,y,-1.72,12);p.rotation.z=Math.PI/2;}for(const x of[-5,5]){box(1.2,1.1,.8,'#9c7355',readyRoom,x,.4,-1.1);glow(.8,.28,.03,'#b6d4b4',readyRoom,x,.73,-.67);}const roomLight=new THREE.PointLight('#f4b66b',22,16,2);roomLight.position.set(0,3,1);readyRoom.add(roomLight);
// Planet B: rust-colored ground, pale cliffs and twelve finite sample instruments.
cylinder(125,125,.5,'#ad7456',frontier,0,-.35,0,96);const rand=(()=>{let s=state.seed;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296;};})();for(let i=0;i<55;i++){const a=rand()*Math.PI*2,d=88+rand()*34,h=3+rand()*10;const r=mesh(new THREE.CylinderGeometry(1.5+rand()*3,3+rand()*4,h,5,1),material(i%2?'#d3bd9d':'#d9c8aa'),frontier,Math.cos(a)*d,h/2-.2,Math.sin(a)*d);r.rotation.y=rand()*6;}
for(const [x,z,r]of[[-12,-10,2.2],[11,-11,2.4],[-14,4,2],[14,5,2.1],[-2,-8,1.8],[0,6,1.6],[-23,15,2.3],[23,17,2.4]]){const g=mesh(new THREE.IcosahedronGeometry(r,0),material('#d3b99c'),frontier,x,r*.65,z);g.scale.set(1,1.25,.8);cover.push({position:new THREE.Vector3(x,r*.65,z),radius:r});}
const cable=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(),new THREE.Vector3(),new THREE.Vector3()]),new THREE.LineBasicMaterial({color:'#65505e'}));props.add(cable);cable.visible=false;
const pedestals=FLAG_SITES.map(([x,z],i)=>{const g=new THREE.Group();g.position.set(x,0,z);frontier.add(g);cylinder(.65,.85,.5,'#6d5e68',g,0,.25,0,8);box(.7,.12,.7,'#c9b596',g,0,.56,0);glow(.35,.035,.03,'#a4e1d0',g,0,.5,.42);return g;});
for(const [i,pos]of LANDING_BAYS.entries()){const g=new THREE.Group();g.position.fromArray(pos);g.scale.set(5,1,5);frontier.add(g);ring(4,.08,FACTIONS[i].color,g,.01);emblem(i,g,0,.03,3);for(let k=0;k<5;k++)box(.3,.025,.5,'#d8bea0',g,-1+k*.5,.01,3.4);}
function flagModel(){const g=new THREE.Group();box(.12,.45,.12,'#786875',g,0,.24,0);const crystal=mesh(new THREE.OctahedronGeometry(.24,0),material('#a6e3cb',0,.5,true),g,0,.67,0);const handle=mesh(new THREE.TorusGeometry(.3,.035,6,18,Math.PI*1.6),material('#cab596'),g,0,.55,0);const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute([0,0,0,.45,-.12,0,0,-.28,0],3));const pennant=mesh(geo,new THREE.MeshBasicMaterial({color:'#92e5cf',side:THREE.DoubleSide,transparent:true,opacity:.55}),g,.04,1.35,0);cylinder(.018,.018,.65,'#c1dbc0',g,.02,1.02,0,6);return {group:g,crystal,pennant};}
const flags=state.match.flags.map(f=>{const v=flagModel();props.add(v.group);v.group.userData.action={type:'science',id:f.id};world.targets.push(v.group);return {...v,flag:f};});
const cargoRack=new THREE.Group();ship.add(cargoRack);for(let i=0;i<8;i++){const x=(i%2?1:-1)*1.25,z=.7+Math.floor(i/2)*.5;box(.5,.05,.44,'#5a4c60',cargoRack,x,.5,z);box(.04,.55,.04,'#b99c7b',cargoRack,x+.22,.8,z+.2);}const optional=new THREE.Group();ship.add(optional);const extraGun=box(.18,.18,1.4,'#e5cfa9',optional,.38,2.75,-.3);const fuelPod=cylinder(.37,.37,1.8,'#e3944d',optional,0,1.1,2.3,16);fuelPod.rotation.x=Math.PI/2;
const beacon=mesh(new THREE.OctahedronGeometry(.45,0),new THREE.MeshBasicMaterial({color:'#ffbc6d',wireframe:true}),props,0,2,0);beacon.visible=false;beacon.userData.action={type:'wreck'};world.targets.push(beacon);
const homePlanet=sphere(18,'#739d96',props,-48,28,-105,48);const cloud=sphere(18.2,'#cfe1ce',props,-48,28,-105,32);cloud.material=new THREE.MeshBasicMaterial({color:'#bdcfc9',transparent:true,opacity:.09});
function update(onSurface,onHome,time){home.visible=onHome;frontier.visible=onSurface;extraGun.visible=state.upgrades.includes('weapons');fuelPod.visible=state.upgrades.includes('reserve');cargoRack.visible=state.phase!=='assembly';cargoRack.children.forEach((o,i)=>o.visible=i<12||state.upgrades.includes('cargo'));const sample=state.match.flags.find(f=>f.state==='site'&&f.scanner===0&&(f.progress>0||f.stage>0));cable.visible=onSurface&&!!sample&&world.actors[1].group.position.distanceTo(world.actors[3].group.position)<6;if(cable.visible){const from=world.actors[1].group.position.clone().add(new THREE.Vector3(0,1.1,0)),to=new THREE.Vector3(...sample.position).setY(.55),mid=from.clone().add(to).multiplyScalar(.5);mid.y=.12;cable.geometry.setFromPoints([from,mid,to]);}for(const v of flags){const f=v.flag;v.crystal.rotation.y=time*.7;v.pennant.rotation.y=Math.sin(time+f.id)*.1;v.group.scale.setScalar(1);v.group.visible=false;if(f.state==='site'&&onSurface){v.group.visible=true;v.group.position.fromArray(f.position);v.group.position.y=.65;}else if(f.state==='ground'&&f.planet==='B'&&onSurface){v.group.visible=true;v.group.position.fromArray(f.position);}else if(f.state==='carried'&&onSurface){v.group.visible=true;let p;if(f.owner===0){p=world.actors[f.carrier].group.position.clone().add(new THREE.Vector3(.55,.7,.25));}else{const t=state.match.teams[f.owner];p=new THREE.Vector3(...t.botPosition).add(new THREE.Vector3(.55,.7,0));}v.group.position.copy(p);}else if(f.state==='onboard'&&f.owner===0&&['flight','surface','landing','docking','delivery','launch'].includes(state.phase)){const list=state.match.flags.filter(n=>n.state==='onboard'&&n.owner===0),i=list.indexOf(f);v.group.visible=true;v.group.scale.setScalar(.55);v.group.position.copy(ship.position).add(new THREE.Vector3((i%2?1:-1)*1.3,.6,.7+Math.floor(i/2)*.5));}else if(f.state==='delivered'&&onHome&&['delivery','debrief'].includes(state.phase)){v.group.visible=true;v.group.scale.setScalar(.65);v.group.position.set(-1.4+(f.id%4)*.9,1,9.6+Math.floor(f.id/4)*.6);}}
const wreck=state.match.wrecks.find(w=>w.flags.some(id=>state.match.flags[id].state==='wreck'));beacon.visible=!!wreck&&state.phase==='flight';if(wreck){beacon.position.fromArray(wreck.position);beacon.position.z=clampZ(beacon.position.z);beacon.rotation.y=time;}for(const v of world.rivalShips){const t=state.match.teams[v.team.id];v.group.visible=!t.eliminated&&(onSurface?t.planet==='B':onHome?t.planet==='A'||t.phase==='outbound'&&t.phaseTime<10:false);if(onSurface){v.group.position.fromArray(LANDING_BAYS[t.id]);v.craft.children.forEach(o=>o.visible=!o.userData.engineFlame);v.craft.position.y=SHIP_Y-.32;v.crew.forEach((a,i)=>{a.group.visible=true;if(i===0)a.group.position.set(-2,-.10,-20);else a.group.position.set(t.botPosition[0]-v.group.position.x+(i===3?0:i===1?-1.5:1.5),-.10,t.botPosition[2]-v.group.position.z+(i===3?0:1.5));});}else if(onHome){v.group.position.set([-60,60,0][t.id-1],0,[-44,-44,-92][t.id-1]);if(t.phase==='launching')v.craft.position.y=SHIP_Y+t.phaseTime*2*SHIP_SCALE;else if(t.phase==='outbound')v.craft.position.y=10*SHIP_SCALE+t.phaseTime*2*SHIP_SCALE;else v.craft.position.y=SHIP_Y-.32;v.crew.forEach(a=>{a.group.visible=['building','systems test','ready'].includes(t.phase);if(state.mode==='play')a.group.position.y=.22;});v.craft.traverse(o=>{if(o.userData.engineFlame)o.visible=['launching','outbound'].includes(t.phase);});}}
}
function clampZ(z){return Math.max(-18,Math.min(18,z));}
return {home,frontier,props,optional,cover,pedestals,flags,receiver,shop,cargoRack,beacon,homePlanet,update,flagModel};}
